func (this *Polymarket) HandleOHLCV(client any, message map[string]any) {
	//
	//     {
	//         "ch": "klines::1::1h",
	//         "ts": 1788547135685,
	//         "ets": 1788547135685,
	//         "sq": 35880657084,
	//         "data": [
	//             [ 1788537600000, "7724.9", "7724.9", "7724.2", "7724.2", "0.02872", 5 ]
	//         ]
	//     }
	//
	// only the candles touched by fresh trades are included, the array can be empty
	//
	var ch *string = this.SafeString(message, "ch", "")
	var parts []string = strings.Split(*ch, "::")
	var marketId *string = this.SafeString(parts, 1)
	var interval *string = this.SafeString(parts, 2)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = this.SafeString(market, "symbol", "")
	var timeframe *string = this.FindTimeframe(interval)
	if timeframe == nil {
		return
	}
	var rows []any = ccxt.SafeListTyped(message, "data")
	var rowsLength int = len(rows)
	if rowsLength == 0 {
		return
	}
	if _, ok := this.Ohlcvs[*symbol]; !ok {
		this.Ohlcvs[*symbol] = map[string]any{}
	}
	if !(ccxt.InOp(this.Ohlcvs[*symbol], timeframe)) {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		stored := ccxt.NewArrayCacheByTimestamp(limit)
		if timeframe != nil {
			this.Ohlcvs[*symbol][*timeframe] = stored
		}
	}
	var ohlcv any
	if timeframe != nil {
		ohlcv = this.Ohlcvs[*symbol][*timeframe]
	}
	for i := 0; i < len(rows); i++ {
		var parsed any = ccxt.OHLCVToList(this.ParseOHLCV(ccxt.DerefScalar(rows[i]), market))
		ohlcv.(ccxt.Appender).Append(parsed)
	}
	var messageHash string = "candles:" + *timeframe + ":" + *symbol
	client.(ccxt.ClientInterface).Resolve(ohlcv, messageHash)
}

/**
 * @method
 * @ignore
 * @name polymarket#authenticate
 * @description authenticates the websocket connection with the session proxy credentials, provisioning them first when needed
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} resolves once the connection is authenticated
 */
func (this *Polymarket) AuthenticateAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[*string] {
	ch := make(chan ccxt.AsyncResult[*string], 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) authenticateBody(ch chan ccxt.AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadProxyCredentialsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	credentials := r.Value
	var url *string = this.SafeString(this.Urls["api"], "ws")
	var client ccxt.ClientInterface = this.Client(url)
	var messageHash string = "authenticated"
	var future any = client.(ccxt.ClientInterface).ReusableFuture(messageHash)
	var authenticated any = client.(ccxt.ClientInterface).SubscriptionSafe(messageHash)
	if authenticated == nil {
		var id int64 = this.RequestId()
		var pending map[string]any = map[string]any{
			"method":           "auth",
			"messageHashes":    []any{messageHash},
			"subMessageHashes": []any{messageHash},
		}
		client.(ccxt.ClientInterface).SubscriptionSet("req:"+strconv.FormatInt(id, 10), pending)
		var request map[string]any = map[string]any{
			"id":  id,
			"req": "post",
			"op": map[string]any{
				"type": "auth",
				"args": map[string]any{
					"proxy":  this.SafeString(credentials, "proxy"),
					"secret": this.SafeString(credentials, "secret"),
				},
			},
		}
		this.Watch(url, messageHash, this.Extend(request, params), messageHash)
	}

	r1 := <-future.(*ccxt.Future).Await()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var resolved *string
	switch resolvedBox := r1.Value.(type) {
	case *string:
		resolved = resolvedBox
	case string:
		resolved = &resolvedBox
	default:
		_ = resolvedBox
	}
	ch <- ccxt.AsyncResult[*string]{Value: resolved}
	return nil
}

/**
 * @method
 * @name polymarket#watchOrders
 * @description watches information on the orders made by the user
 * @see https://docs.polymarket.com/perps/realtime-updates
 * @param {string} [symbol] unified market symbol of the market the orders were made in
 * @param {int} [since] timestamp in ms of the earliest order
 * @param {int} [limit] the maximum number of order structures to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/#/?id=order-structure}
 */
func (this *Polymarket) WatchOrdersAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[[]ccxt.Order] {
	ch := make(chan ccxt.AsyncResult[[]ccxt.Order], 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) watchOrdersBody(ch chan ccxt.AsyncResult[[]ccxt.Order], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}

	r1 := <-this.AuthenticateAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var messageHash string = "orders"
	var symbolResolved *string = symbol
	if symbol != nil {
		var market map[string]any = this.Market(symbol)
		var resolvedSymbol *string = this.SafeString(market, "symbol", "")
		symbolResolved = resolvedSymbol
		messageHash = "orders:" + *resolvedSymbol
	}
	var subscribeHashes []any = []any{"orders"}
	var request map[string]any = this.SendSubscription("sub", []any{"orders"}, []any{messageHash}, subscribeHashes, map[string]any{}, params, subscribeHashes)
	var url *string = this.SafeString(this.Urls["api"], "ws")

	r2 := <-this.Watch(url, messageHash, request, "orders")
	if r2.Err != nil {
		panic(r2.Err)
	}
	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(r2.Value)
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(symbolResolved, limitResolved)
	}

	ch <- ccxt.AsyncResult[[]ccxt.Order]{Value: ccxt.OrdersFromList(this.FilterBySymbolSinceLimit(orders, symbolResolved, since, limitResolved, true))}
	return nil
}
func (this *Polymarket) HandleOrder(client any, message any) {
	//
	//     {
	//         "ch": "orders",
	//         "ts": 1788546565800,
	//         "sq": 35879860000,
	//         "data": {
	//             "oid": 1234567890,
	//             "iid": 6,
	//             "buy": true,
	//             "p": "79000.0",
	//             "qty": "0.001",
	//             "tif": "gtc",
	//             "po": false,
	//             "ro": false,
	//             "rest": "0.001",
	//             "fill": "0",
	//             "cts": 1788546565789,
	//             "uts": 1788546565789,
	//             "status": "open"
	//         }
	//     }
	//
	var data any = this.SafeValue(message, "data")
	var rows []any = []any{}
	if ccxt.IsArray(data) {
		rows = ccxt.ArrayTyped(data)
	} else {
		rows = append(rows, data)
	}
	var rowsLength int = len(rows)
	if rowsLength == 0 {
		return
	}
	if this.Orders == nil {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var stored any = this.Orders
	var symbols map[string]any = map[string]any{}
	for i := 0; i < rowsLength; i++ {
		var row map[string]any = this.SafeDictMap(rows, i, map[string]any{})
		var parsed map[string]any = ccxt.OrderToMap(this.ParseOrder(row))
		stored.(ccxt.Appender).Append(parsed)
		var symbol *string = this.SafeString(parsed, "symbol")
		if symbol != nil {
			symbols[*symbol] = true
		}
	}
	client.(ccxt.ClientInterface).Resolve(stored, "orders")
	var symbolKeys []string = nil
	if symbols != nil {
		symbolKeys = make([]string, 0, len(symbols))
		for objectKey := range symbols {
			symbolKeys = append(symbolKeys, objectKey)
		}
	}
	for i := 0; i < len(symbolKeys); i++ {
		var symbol *string = this.SafeString(symbolKeys, i, "")
		client.(ccxt.ClientInterface).Resolve(stored, "orders:"+*symbol)
	}
}

